import React, { useState, useEffect } from 'react';

const API = 'http://localhost:5000/api';

function RentGame({ user }) {
  const [games, setGames] = useState([]);
  const [selectedGame, setSelectedGame] = useState('');
  const [copies, setCopies] = useState([]);
  const [selectedCopy, setSelectedCopy] = useState('');
  const [rentalDays, setRentalDays] = useState(7);
  const [msg, setMsg] = useState({ type: '', text: '' });
  const [rentals, setRentals] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch(`${API}/games`).then(r => r.json()).then(d => setGames(Array.isArray(d) ? d : d.games || [])).catch(() => {});
    fetchRentals();
  }, []);

  useEffect(() => {
    if (!selectedGame) return setCopies([]);
    fetch(`${API}/games/${selectedGame}/digital-copies`)
      .then(r => r.json())
      .then(d => setCopies(Array.isArray(d) ? d : []))
      .catch(() => setCopies([]));
  }, [selectedGame]);

  const fetchRentals = async () => {
    try {
      const res = await fetch(`${API}/rentals/user/${user.userID || user.id}`);
      const data = await res.json();
      setRentals(Array.isArray(data) ? data : []);
    } catch { setRentals([]); }
  };

  const handleRent = async (e) => {
    e.preventDefault();
    setMsg({ type: '', text: '' });
    if (!selectedCopy) return setMsg({ type: 'error', text: 'Select a copy.' });
    setLoading(true);
    try {
      const res = await fetch(`${API}/rentals/rent`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: user.userID || user.id, copyId: selectedCopy, rentalDays })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || data.error || 'Failed');
      setMsg({ type: 'success', text: 'Game rented successfully!' });
      setSelectedGame(''); setSelectedCopy(''); setRentalDays(7);
      fetchRentals();
    } catch (err) {
      setMsg({ type: 'error', text: err.message });
    }
    setLoading(false);
  };

  const handleReturn = async (rentalId) => {
    try {
      const res = await fetch(`${API}/rentals/return/${rentalId}`, { method: 'PUT' });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || 'Failed');
      setMsg({ type: 'success', text: 'Game returned!' });
      fetchRentals();
    } catch (err) {
      setMsg({ type: 'error', text: err.message });
    }
  };

  return (
    <div>
      <h2 style={heading}>Rent a Game</h2>

      {msg.text && <p style={{ color: msg.type === 'success' ? '#00ff88' : '#fc8181', marginBottom: '1rem' }}>{msg.text}</p>}

      <div style={card}>
        <form onSubmit={handleRent}>
          <div style={formGroup}>
            <label style={label}>Select Game</label>
            <select style={select} value={selectedGame} onChange={e => { setSelectedGame(e.target.value); setSelectedCopy(''); }} required>
              <option value="">-- Choose a game --</option>
              {games.map((g, i) => <option key={g.gameID || i} value={g.gameID || g.id}>{g.title || g.name}</option>)}
            </select>
          </div>
          <div style={formGroup}>
            <label style={label}>Digital Copy</label>
            <select style={select} value={selectedCopy} onChange={e => setSelectedCopy(e.target.value)} required>
              <option value="">-- Choose a copy --</option>
              {copies.map((c, i) => (
                <option key={c.copyID || i} value={c.copyID || c.id}>
                  Copy #{c.copyID || c.id} — {c.isAvailable || c.availability === 1 ? 'Available' : 'Unavailable'}
                </option>
              ))}
            </select>
          </div>
          <div style={formGroup}>
            <label style={label}>Rental Days</label>
            <input style={inputStyle} type="number" min={1} max={30} value={rentalDays}
              onChange={e => setRentalDays(Number(e.target.value))} />
          </div>
          <button type="submit" style={primaryBtn} disabled={loading}>{loading ? 'Processing...' : 'Rent Now'}</button>
        </form>
      </div>

      <h3 style={{ ...heading, marginTop: '2rem' }}>My Rentals</h3>
      <table style={table}>
        <thead>
          <tr>{['Game', 'Rented On', 'Due Date', 'Status', 'Action'].map(h => <th key={h} style={th}>{h}</th>)}</tr>
        </thead>
        <tbody>
          {rentals.length === 0
            ? <tr><td colSpan={5} style={{ ...td, color: '#aaa', textAlign: 'center' }}>No rentals yet</td></tr>
            : rentals.map((r, i) => (
              <tr key={r.rentalID || i}>
                <td style={td}>{r.gameTitle || r.title || `Game #${r.gameID}`}</td>
                <td style={td}>{r.rentalDate ? new Date(r.rentalDate).toLocaleDateString() : '—'}</td>
                <td style={td}>{r.dueDate ? new Date(r.dueDate).toLocaleDateString() : '—'}</td>
                <td style={td}>
                  <span style={{ color: r.status === 'active' ? '#00ff88' : '#aaa' }}>
                    {r.status || 'active'}
                  </span>
                </td>
                <td style={td}>
                  {(r.status === 'active' || !r.returnDate) && (
                    <button onClick={() => handleReturn(r.rentalID || r.id)}
                      style={{ ...primaryBtn, width: 'auto', padding: '0.3rem 0.75rem', fontSize: '0.8rem' }}>
                      Return
                    </button>
                  )}
                </td>
              </tr>
            ))}
        </tbody>
      </table>
    </div>
  );
}

const heading = { color: '#fff', marginBottom: '1rem' };
const card = { background: '#1a1a2e', padding: '1.5rem', borderRadius: 12, marginBottom: '1.5rem', maxWidth: 500 };
const formGroup = { marginBottom: '1rem' };
const label = { display: 'block', color: '#aaa', fontSize: '0.85rem', marginBottom: '0.4rem' };
const select = { width: '100%', padding: '0.6rem 1rem', background: '#0f0f1a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: '0.9rem' };
const inputStyle = { width: '100%', padding: '0.6rem 1rem', background: '#0f0f1a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: '0.9rem' };
const primaryBtn = { width: '100%', padding: '0.65rem', background: '#00d4ff', color: '#000', border: 'none', borderRadius: 8, fontWeight: 700, cursor: 'pointer', fontSize: '0.95rem' };
const table = { width: '100%', borderCollapse: 'collapse' };
const th = { textAlign: 'left', padding: '0.75rem 1rem', color: '#aaa', fontSize: '0.8rem', borderBottom: '1px solid #333', textTransform: 'uppercase' };
const td = { padding: '0.75rem 1rem', color: '#ccc', borderBottom: '1px solid #222', fontSize: '0.9rem' };

export default RentGame;
